function isWebProject(project: unknown): boolean {
  const t = (project as { type?: unknown } | null)?.type;
  return typeof t === "string" && t.toLowerCase() === "web";
}

const MEDIA_TYPES = new Set(["video", "gif", "image"]);

/**
 * 首帧看门狗默认上限（见 armWatchdog）。相当宽：它要抓的是「循环已死」，
 * 不是「这次有点慢」——真实装配（含 100MB+ 场景包）在数秒内出首帧。
 */
const MOUNT_WATCHDOG_MS = 60000;

function mediaProjectType(project: unknown): string | null {
  const t = (project as { type?: unknown } | null)?.type;
  if (typeof t !== "string") return null;
  const lower = t.toLowerCase();
  return MEDIA_TYPES.has(lower) ? lower : null;
}

/**
 * 场景需要真 canvas。`reuse=false` 时必换新画布：`loseContext()` 异步生效，
 * `isContextLost()` 不可信；建过 GL 的旧画布重挂会拿到死上下文（黑屏）。
 */
function ensureSceneCanvas(el: HTMLElement): HTMLCanvasElement {
  if (el instanceof HTMLCanvasElement) return el;
  const existing = el.querySelector(":scope > canvas[data-webwallgl]");
  if (existing instanceof HTMLCanvasElement) {
    // 只要这块画布**建过 GL 上下文**，它的上下文就一定已经不可用：destroy()/release()
    // 走 renderer.dispose() → loseContext()，而 loseContext 异步生效，同步查
    // isContextLost() 不可信（见 remountCurrent 的说明）。所以「建过就换」，不看调用方。
    // 原先有个 reuse=true 的快捷路径，导致 destroy() 之后再 mount() 到同一容器会
    // 复用那块**死画布**（黑屏）—— docs/ENGINE-REVIEW-2026-10.md §3.3。
    if (existing.getAttribute("data-webwallgl-gl") !== "1") return existing;
    existing.remove();
  }
  const c = document.createElement("canvas");
  c.setAttribute("data-webwallgl", "1");
  c.style.cssText = "position:absolute;inset:0;width:100%;height:100%;display:block;";
  if (getComputedStyle(el).position === "static") el.style.position = "relative";
  el.appendChild(c);
  return c;
}

/** 装配中途退出时回收「库自建的那块画布」（调用方自己传的画布不碰）。 */
function releaseOwnCanvas(cfg: { canvas?: unknown }, el: HTMLElement) {
  const c = cfg.canvas;
  if (c instanceof HTMLCanvasElement && c !== el && c.parentElement) c.remove();
}

async function resolveMountConfig(
  el: HTMLElement,
  o: MountOptions,
): Promise<WallpaperConfig> {
  const base = {
    fit: normalizeFit(o.fit as WallpaperFit | undefined),

    // 0 = 自动跟随设备 DPR（Retina 原生清晰，默认）；显式正数 = 目标 DPR
    renderDpr: o.renderDpr ?? 0,
    // 视频纹理上传倍率：0 = 自动（帧率守门按实测压）；正数 = 固定（1 = 不压）。
    // 原样透传，规范化在消费方（scene-mount 走 normalizeVideoTexScale）。
    videoTexScale: o.videoTexScale ?? 0,
    sceneFps: o.fps ?? 60,
    muted: (o.volume ?? 0) <= 0,
    loop: true,
    canvas: el,
    source: o.source,
    // 质量设置（抗锯齿/粒子/后处理档位）。原样透传：规范化在消费方做
    // （scene-mount applyQuality / getQuality），这里不引依赖 —— 本函数会被
    // verify-media 抽出来脱离 import 单独执行。
    quality: o.quality,
  };
  let project: unknown = null;
  try {
    project = (await o.source.project?.()) ?? null;
  } catch {
    project = null;
  }
  if (isWebProject(project)) {
    let url: string | undefined;
    try {
      const entry = await o.source.webEntry?.();
      url = entry?.url;
    } catch {
      url = undefined;
    }
    if (!url && o.source.key) {
      // httpSource.key 就是 baseUrl；无 webEntry 时兜底 index.html
      const file =
        project && typeof (project as { file?: unknown }).file === "string"
          ? String((project as { file: string }).file).trim().replace(/^\/+/, "") || "index.html"
          : "index.html";
      url = `${o.source.key.replace(/\/+$/, "")}/${file}`;
    }
    if (!url) throw new Error("网页壁纸：无法解析入口 URL（需要 Source.webEntry 或 httpSource）");
    return { ...base, type: "web", src: url, source: o.source };
  }
  // 媒体壁纸（video / gif / image）：dispatch 路由到 mountMedia，需要一个 src URL。
  // 与 web 分支同构的三段式：Source.mediaEntry() → {key}/{project.file} → 抛错。
  // 兜底这一段是给「自己实现 Source 但没实现 mediaEntry」的调用方留的，
  // 只要 key 是个 HTTP 基址就还能拼出来；bytesSource/fileSource 没有 key，
  // 也确实拿不到视频地址（本地字节里没有这个信息），此时如实抛错。
  const mediaType = mediaProjectType(project);
  if (mediaType) {
    let url: string | undefined;
    let entryType: string | undefined;
    try {
      const entry = await o.source.mediaEntry?.();
      url = entry?.url;
      entryType = entry?.type;
    } catch {
      url = undefined;
    }
    if (!url && o.source.key) {
      const file =
        project && typeof (project as { file?: unknown }).file === "string"
          ? String((project as { file: string }).file).trim().replace(/^\/+/, "")
          : "";
      // 媒体没有 index.html 那样的惯例文件名，缺 file 就别猜（猜必 404）
      if (file) url = `${o.source.key.replace(/\/+$/, "")}/${file}`;
    }
    if (!url) {
      throw new Error(
        `媒体壁纸（${mediaType}）：无法解析资源 URL（需要 Source.mediaEntry 或 project.file + httpSource）`,
      );
    }
    // mediaEntry 显式给的 type 可纠正 project.json（作者把 gif 标成 image 之类）
    const finalType = MEDIA_TYPES.has(String(entryType).toLowerCase())
      ? String(entryType).toLowerCase()
      : mediaType;
    // 视频走 DOM 直显：不建画布（白占一个 WebGL 上下文名额，且 instance.canvas
    // 会指向一块永远空白的画布，误导调用方）。canvas 字段保留调用方给的容器
    // 元素本身 —— mountVideoDom 要靠它定位挂载点。
    const canvas = finalType === "video" ? el : ensureSceneCanvas(el);
    return { ...base, type: finalType as WallpaperConfig["type"], src: url, canvas, source: o.source };
  }
  // [1.3.0] project.type 缺失或不认识时，按资源 URL 的扩展名嗅探。
  // 两道闸门，缺一不可：
  //  · 只在 Source 提供了 mediaEntry 时才试——有 mediaEntry 就说明调用方本来
  //    就想放一段媒体；对普通 httpSource（壁纸包目录）不嗅探，免得把没有
  //    project.json 的场景壁纸误判成媒体。
  //  · **project.type 已经明确声明过就绝不覆盖**（哪怕它声明的是 scene）。
  //    作者说了算：某些场景壁纸的 project.file 确实指向 .mp4（那是场景里的
  //    视频纹理素材，不是"这张壁纸是个视频"），嗅探覆盖它会整张壁纸走错路径。
  const declaredType =
    typeof (project as { type?: unknown } | null)?.type === "string"
      ? String((project as { type: string }).type).trim()
      : "";
  if (!declaredType && typeof o.source.mediaEntry === "function") {
    let url: string | undefined;
    let entryType: string | undefined;
    try {
      const entry = await o.source.mediaEntry();
      url = entry?.url;
      entryType = entry?.type;
    } catch {
      url = undefined;
    }
    const sniffed =
      (MEDIA_TYPES.has(String(entryType).toLowerCase()) ? String(entryType).toLowerCase() : null) ??
      (url ? sniffMediaType(url) : null);
    if (url && sniffed) {
      // 同上：嗅探出视频时也不建画布，canvas 保留容器元素供 mountVideoDom 定位
      const canvas = sniffed === "video" ? el : ensureSceneCanvas(el);
      return { ...base, type: sniffed as WallpaperConfig["type"], src: url, canvas, source: o.source };
    }
  }
  // 其余一律走场景装配。
  // src 填工坊 ID（从 source.key 末段抽出）：scene-mount 用它作 workshopId
  // 喂视差白名单；缺了会让 3233141951 等墙在 Source API 路径下退回 legacy。
  const canvas = ensureSceneCanvas(el);
  const workshopId = workshopIdFromSourceKey(o.source.key);
  return {
    ...base,
    type: "scene",
    canvas,
    source: o.source,
    ...(workshopId ? { src: workshopId } : {}),
  };
}

/**
 * 同步创建实例。加载由后续 load() 或内部 applyOptions 驱动；
 * 一般使用者请用 mount()。
 */
export function createScene(
  el: HTMLElement,
  options?: Partial<Omit<MountOptions, "source">>,
): SceneInstance {
  const rt: Runtime = createRuntime();
  const events: {
    ready: Array<SceneEvents["ready"]>;
    error: Array<SceneEvents["error"]>;
    diagnostic: Array<SceneEvents["diagnostic"]>;
  } = { ready: [], error: [], diagnostic: [] };

  let currentOptions: MountOptions = { ...(options ?? {}), source: null as unknown as Source };

  // 对外仍暴露 .canvas：场景是真 canvas；网页是传入的容器元素
  let boundEl: HTMLElement = el;

  // [we-scene patch] 实例终态与代际（docs/ENGINE-REVIEW-2026-10.md §3.3）。
  //
  // 没有它们时的两个洞：destroy() 落在 `await resolveMountConfig` 的窗口里不生效 ——
  // 异步体接着往下走，在一个已销毁的 runtime 上装配出完整场景 + rAF（「复活」）；
  // 同理 load(A) 的 await 期间再来 load(B)，A 的尾巴会把 B 的配置覆盖掉。
  // destroyed 是**终态**（destroy 之后所有公开方法只 no-op，不复活）；
  // gen 是**代际**（同一实例上的连续 load/mount 各自一代，旧代在每个 await 后自行退出）。
  let destroyed = false;
  let gen = 0;
  const beginGen = () => ++gen;
  const isCurrent = (g: number) => g === gen && !destroyed;
  /**
   * 当前这一代「等首帧」的收尾钩子。destroy() 用它把挂起的 mount()/load() 明确拒掉 ——
   * 否则代际作废之后那个 Promise 永远不落地（看门狗也因代际核对而不触发），
   * 又变回 issue #9 要消灭的「既不 resolve 也不 reject」黑洞。
   * 注意：被**新的 load 取代**（而非 destroy）时故意不落地 —— 那一次装配的结论已经
   * 没人关心，而新的一代自带自己的 Promise；调用方想确定收尾就 await 每一次 load。
   */
  let settlePending: (() => void) | null = null;

  const emitError = (err: Error) => {
    for (const fn of events.error) {
      try {
        fn(err);
      } catch {
        /* 订阅者抛错不打断渲染 */
      }
    }
  };

  const wireOptions = (o: MountOptions) => {
    // 库实例默认**不**读宿主页上的调试全局（见 MountOptions.debugHooks 的说明）
    rt.debugHooks = o.debugHooks === true;
    rt.onDiagnostic = (msg, level) => {
      try {
        o.onDiagnostic?.(msg, level);
      } catch {
        
      }
      for (const fn of events.diagnostic) {
        try {
          fn(msg, level);
        } catch {
          /* 忽略 */
        }
      }
    };
    rt.onError = (err) => {
      try {
        o.onError?.(err);
      } catch {
        /* 忽略 */
      }
      emitError(err);
    };
    rt.onSceneInfo = (info) => {
      rt.info = info;
    };
    // 音频频谱源：拉模式，渲染循环每帧调一次。只在选项里显式出现时才动
    // rt.audioBridge —— 否则 load() 换场景会把 setAudio() 装好的宿主源
    // 冲回 undefined（挂载选项里本来就没有 audio 这一项）。
    if ("audio" in o) applyAudio(o.audio ?? null);
    // 媒体源同理：只在选项里显式出现时才动 rt.mediaSource，否则 load() 换场景
    // 会把 setMedia() 装好的宿主源冲掉
    if ("media" in o) {
      rt.mediaSource = o.media ?? null;
      // 显式传 null = 禁用（不是"回落模拟源"）；见 Runtime.mediaDisabled
      rt.mediaDisabled = o.media === null;
    }
    // 遮挡分档配置（V5）：同 audio/media 纪律，只在选项里显式出现时才动 ——
    // load() 换场景不冲掉已生效配置；false = 显式关闭（setOcclusion 静默无效）
    if ("occlusion" in o) {
      rt.occlusionCfg = o.occlusion === false ? false : normalizeOcclusionConfig(o.occlusion);
    }
  };

  /**
   * 把公共 AudioSource 接到运行时的拉模式桥。
   * `null` 是**显式禁用**（频谱恒为 0），与"从没设置过"不同——后者才回落模拟源。
   */
  const applyAudio = (src: AudioSource | null) => {
    rt.audioDisabled = src === null;
    if (!src) {
      rt.audioBridge = null;
      return;
    }
    rt.audioBridge = () => {
      try {
        const s = src.snapshot();
        // 返回 null 是「本帧无数据」的合法信号，引擎会回落模拟源；
        // 提供方抛错也按无数据处理，不让一次异常掀掉整个渲染循环。
        return s && s.left && s.right ? s : null;
      } catch {
        return null;
      }
    };
  };

  const armFirstFrame = (g: number): Promise<void> => {
    return new Promise<void>((resolve, reject) => {
      settlePending = () => {
        settlePending = null;
        reject(new Error("实例已销毁：挂载/加载未完成"));
      };
      const prev = rt.onFirstFrame;
      rt.onFirstFrame = () => {
        rt.onFirstFrame = undefined;
        // 旧代的回调可能被新代链着（prev?.()）：只让**本代**的 Promise 落地，
        // 否则 clear→重挂后旧代在飞的帧会提前 resolve 新代的 mount()。
        if (!isCurrent(g)) return;
        settlePending = null;
        prev?.();
        const info = (rt.info as SceneInfo) ?? {
          width: 0,
          height: 0,
          layerCount: 0,
          hasModels: false,
          hasParticles: false,
          hasText: false,
        };
        try {
          currentOptions.onReady?.(info);
        } catch {
          /* 忽略 */
        }
        for (const fn of events.ready) {
          try {
            fn(info);
          } catch {
            /* 忽略 */
          }
        }
        resolve();
      };
    });
  };

  const armFailure = (g: number): { promise: Promise<never>; off: () => void } => {
    let off: () => void = () => {};
    const promise = new Promise<never>((_, reject) => {
      // 事件总线是**实例级**的（跨代共享）：不加代际核对时，旧代装配失败会顺手把
      // 新代正在等的 Promise 也 reject 掉（两代共用一个 error 通道）。
      off = instance.on("error", (e) => {
        if (isCurrent(g)) reject(e);
      });
    });
    return { promise, off };
  };

  /**
   * 首帧看门狗（issue #9）：`mount()` 的 Promise 只由 onFirstFrame / onError 落地，
   * 两者都不触发就是**永久挂起** —— 调用方既拿不到成功也拿不到失败，无法区分
   * 「还在加载」和「已经死了」。挂表超时后 reject + 上报诊断，把黑洞变成结论。
   *
   * 默认 60000ms（`mountTimeoutMs` 可调，0 = 关闭）。取这个量级是因为首帧成本
   * 与 pkg 体积/解码相关：本机最大的 100MB+ 场景包也在数秒内出首帧，60s 只可能
   * 是「真死了」。超时**不**销毁实例：调用方拿到 reject 后仍可自行 destroy()，
   * 也可能选择继续等（极慢的冷启动），这里不替它做决定。
   */
  const armWatchdog = (g: number): { promise: Promise<never>; off: () => void } => {
    const ms = currentOptions.mountTimeoutMs === undefined ? MOUNT_WATCHDOG_MS : Number(currentOptions.mountTimeoutMs);
    if (!Number.isFinite(ms) || ms <= 0) return { promise: new Promise<never>(() => {}), off: () => {} };
    let timer: ReturnType<typeof setTimeout>;
    const promise = new Promise<never>((_, reject) => {
      timer = setTimeout(() => {
        // 代际核对：被取代/已销毁的那一代不该再报超时（它早已不是调用方在等的那件事）
        if (!isCurrent(g)) return;
        const err = new Error(
          `mount 首帧超时（${Math.round(ms)}ms）：渲染循环没有产出首帧，也没有触发 onError。` +
            `若不是在极慢的冷启动，多半是渲染循环已无声死亡 —— 开 onDiagnostic 看最后一条诊断。` +
            `（可用 mountTimeoutMs 调整或传 0 关闭本看门狗）`,
        );
        reportDiag(rt, rt.cfg, `failed: mount 首帧超时 ${Math.round(ms)}ms（渲染循环无首帧、无 onError）`, "error");
        reject(err);
      }, ms);
    });
    return { promise, off: () => clearTimeout(timer) };
  };

  /**
   * 用当前配置原地重挂（setRenderDpr / restore 共用）。
   *
   * 必须换画布，不能沿用 `rt.cfg.canvas`：`clear()` 里 `renderer.dispose()` 调
   * `WEBGL_lose_context.loseContext()`，那块画布的 GL 上下文就废了 ——
   * 同一 canvas 再 `getContext("webgl2")` 拿回的还是那个 lost 对象。
   * 而 `loseContext()` 是**异步生效**的，`clear()` 之后同步查 `isContextLost()`
   * 仍是 false，所以只能按「建过上下文就换」这个确定性事实决策
   * （ensureSceneCanvas 里「建过 GL 就换」这条规则），不去猜它此刻死没死。
   *
   * 先 clear 再换画布：clear 要读 `rt.canvas` 等旧引用做回收，换早了就漏。
   * 装配函数开头自己也会 clear 一次，幂等，多调只是空转。
   *
   * 只对**用 WebGL 的**路径需要。网页壁纸挂 iframe、视频壁纸挂 `<video>`
   * DOM 直显，两者都不碰 GL 上下文，重挂时不该动画布（对视频尤其重要：
   * 去换画布会把 `data-webwallgl-gl` 的干净画布白删一次，还可能把调用方
   * 传的 canvas 误判成"上下文已死"而直接报错）。
   * 调用方**直接传 canvas** 时换不掉（库不能替它换 DOM），如实报错。
   */
  const remountCurrent = () => {
    const usesGL = rt.cfg.type !== "web" && rt.cfg.type !== "video";
    if (usesGL) {
      clear(rt);
      if (el instanceof HTMLCanvasElement) {
        emitError(
          new Error(
            "重挂失败：调用方直接传入了 canvas，其 WebGL 上下文已在卸载时归还且" +
              "无法复活（loseContext 后同一 canvas 拿不回可用上下文），而库不能替" +
              "调用方替换 DOM。请改传一个空容器让库自建画布，或重新调用 mount()。",
          ),
        );
        return;
      }
      const fresh = ensureSceneCanvas(el);
      if (fresh !== rt.cfg.canvas) {
        rt.cfg = { ...rt.cfg, canvas: fresh };
        boundEl = fresh;
      }
    }
    mountWallpaper(rt, rt.cfg);
  };

  const instance: SceneInstance = {
    get canvas() {
      return boundEl as HTMLCanvasElement;
    },

    pause() {
      rt.paused = true;
      rt.sceneCtl?.pause();
      // 视频壁纸走 DOM 直显，没有 sceneCtl —— 不显式处理这四个方法对它就是空操作
      for (const p of rt.videoPairs ?? []) p.pause();
      if (!rt.videoPairs?.length) rt.video?.pause();
    },
    resume() {
      rt.paused = false;
      resetFrameMeter(rt);
      rt.sceneCtl?.resume();
      // pair.resume() 同时重启预热调度的 rAF：只 play() 主元素会让恢复后的
      // 第一圈退回原生 loop（循环卡顿重现）
      if (rt.videoPairs?.length) {
        for (const p of rt.videoPairs) p.resume();
      } else if (rt.video) {
        void rt.video.play().catch(() => {});
      }
    },
    get paused() {
      return !!rt.paused;
    },

    setFit(fit: Fit) {
      rt.cfg.fit = fit;
      resetCoverAlign(rt);
      // 网页壁纸的 fit 由 iframe 的视口尺寸/偏移表达，不是相机参数：
      // 只改 cfg 画面不会有任何变化，必须触发一次重排（整页渲染器一直是这么做的，
      // 库入口漏了这一步，症状是 wp.setFit("contain") 对网页壁纸完全无反应）。
      rt.webRelayout?.();
      // DOM 直显的视频壁纸同理：fit 表达在 object-fit 上，不改样式画面不动。
      // 双元素时两个都要改，否则交接后 fit 变回旧值。
      const f = fitObjectFit(fit);
      const applyFit = (el: HTMLElement) => {
        el.style.objectFit = f.objectFit;
        el.style.background = f.background;
        el.style.objectPosition = "50% 50%";
      };
      for (const p of rt.videoPairs ?? []) {
        for (const el of [p.active, p.standby]) if (el.isConnected) applyFit(el);
      }
      if (!rt.videoPairs?.length && rt.video?.isConnected) applyFit(rt.video);
    },
    setFps(fps: number) {
      rt.cfg.sceneFps = fps;
      // [遮挡审计 P2 收敛] 与 main.ts 的 setSceneFps 收敛到同一口径：web shim 是
      // **推送式**的，档位收敛必须在下发那一刻做（遮挡只往下压、不抬升宿主上限；
      // pause 档整页已停，直接播宿主值）——原先这里直推裸 fps，处于 light/heavy
      // 档的网页壁纸会被一行 setFps 顶回满帧，且因同档心跳不复述而不会自愈。
      // scene / media 有库侧渲染循环逐帧读 rt.cfg.sceneFps 自行收敛，这里不必管。
      // 通道也从 weShimCall 换成 weShimSend：跨源/严格沙箱网页壁纸下 contentWindow
      // 不可达，直调会静默丢弃帧率设置（shim 侧 message 通道落到同一批实现上）。
      const band = rt.occlusion?.band;
      const n = band && band !== "pause" ? occlusionFpsCap(band, occlusionCfgOf(rt), fps) : fps;
      weShimSend(rt, "setFps", { n });
    },
    setVolume(volume: number) {
      const v = Math.max(0, Math.min(1, volume));
      // 记住精确值：库内部重挂（setRenderDpr/restore 等）重建媒体元素后由
      // reapplyVolume 原样重放，否则只剩 cfg.muted 的 0/1 近似（中间音量丢失）
      rt.userVolume = v;
      rt.cfg.muted = v <= 0;
      rt.sceneAudio?.setVolume(v);
      weShimCall(rt, (w) => w.__weSetVolume?.(v));
      // 双元素循环对自己管音量与静音（备用侧恒静音防双声）
      if (rt.videoPairs?.length) {
        for (const p of rt.videoPairs) p.setVolume(v);
      } else if (rt.video) {
        rt.video.volume = v;
        rt.video.muted = v <= 0;
      }
      // 取消静音曾把视频从 WebCodecs 静音循环切到 A/B <video>（要音轨）；
      // 音量回到 0 时对称地切回去 —— WebCodecs 路径循环点帧级精确、
      // 帧率上限真正生效，不该一直停在 A/B 上。
      // 重挂走 mountVideoDom → clear → WebCodecs 分支，代价是视频从头播放；
      // 解码失败过的源已被 media.ts 清零标记，不会反复尝试
      if (v <= 0 && rt.webcodecsPreferred && rt.cfg.type === "video") {
        remountCurrent();
      }
    },
    setRenderDpr(dpr: number) {
      rt.cfg.renderDpr = dpr;
      remountCurrent();
    },

    // 质量设置热更：就地生效不重挂载（与 setRenderDpr 不同）。与 setAudio 同纪律
    // 合并进 currentOptions —— load() 换场景、restore() 重挂之后仍保持。
    setQuality(patch: QualityOptions) {
      const merged = { ...normalizeQuality(currentOptions.quality ?? rt.cfg.quality), ...(patch ?? {}) };
      currentOptions = { ...currentOptions, quality: merged };
      rt.cfg.quality = merged;
      rt.sceneCtl?.setQuality?.(patch ?? {});
    },
    getQuality(): ResolvedQuality {
      // 读**生效值**：自动降档（软件渲染预设 / 帧率守门）只改 rt.qualityEffective，
      // 这里若读 cfg.quality 会让宿主以为请求值生效了，进而看不出为什么画质变差。
      return rt.qualityEffective ?? normalizeQuality(currentOptions.quality ?? rt.cfg.quality);
    },

    // 视频纹理上传倍率热更（画质页「视频纹理清晰度」）：0 = 自动（帧率守门接管），
    // 正数 = 固定（1 = 不压最清晰、0.5 = 半幅最省）。就地生效、不重挂载；
    // 与 setQuality 同纪律合并进 currentOptions —— load()/restore() 后仍保持。
    setVideoTexScale(scale: number) {
      const v = normalizeVideoTexScale(scale);
      currentOptions = { ...currentOptions, videoTexScale: v };
      rt.cfg.videoTexScale = v;
      rt.sceneCtl?.setVideoTexScale?.(v);
    },
    /** 当前**请求**的倍率（0 = 自动）。生效值（含守门下坡结果）见诊断上报。 */
    getVideoTexScale(): number {
      return normalizeVideoTexScale(rt.cfg.videoTexScale);
    },

    /**
     * 遮挡推送（V5，见 SceneInstance.setOcclusion 与 OcclusionPayload 的契约）。
     * 推送管线在 shell.pushOcclusion（分档/滞回/fail-open）；这里只补一类媒体：
     * **A/B 视频循环对**（video 壁纸 DOM 路径，mountAbPair）没有 sceneCtl 钩子，
     * 跨界时直接停/启。门控必须看 sceneCtl?.setOccluded 是否存在 —— scene 壁纸
     * 的 rt.videoPairs 装的是**全部**场景视频纹理（含隐藏层/脚本停用层），其恢复
     * 由 sceneCtl.setOccluded→resumeImpl 按 pause 时捕获的清单精确还原；这里若
     * 无差别 resume() 会把从不播放的隐藏层视频全部起播（评审 P0：解码/纹理上传
     * 开销凭空回来）。其余路径（scene/web/webcodecs）同理由 setOccluded 接管。
     * 用户暂停（rt.paused）期间解除遮挡不启媒体。
     */
    setOcclusion(payload: OcclusionPayload | null) {
      const prevBand = rt.occlusion?.band;
      pushOcclusion(rt, payload);
      const band = rt.occlusion?.band;
      if (band === prevBand) return;
      if (rt.sceneCtl?.setOccluded) return; // 有 sceneCtl 钩子的路径已由 pushOcclusion 处理
      if (band === "pause") {
        for (const p of rt.videoPairs ?? []) p.pause();
        if (!rt.videoPairs?.length) rt.video?.pause();
      } else if (prevBand === "pause" && !rt.paused) {
        if (rt.videoPairs?.length) {
          for (const p of rt.videoPairs) p.resume();
        } else if (rt.video) {
          void rt.video.play().catch(() => {});
        }
      }
    },

    setProperties(props: Record<string, PropertyValue>) {
      const wire: Record<string, { value: unknown }> = {};
      for (const [k, v] of Object.entries(props)) wire[k] = { value: v };
      rt.sceneCtl?.applyUserProperties(wire);
    },
    getProperties() {
      return { ...(rt.liveUserProps ?? {}) } as Record<string, PropertyValue>;
    },

    // 宿主频谱源。只存引用，实际每帧拉取在 scene-mount 的渲染循环里。
    // 与 __wp.setAudioBridge 同纪律：换场景不清空，装一次对之后所有场景生效
    // （wireOptions 也只在选项里出现 audio 时才覆盖，见那里的说明）。
    setAudio(src: AudioSource | null) {
      currentOptions = { ...currentOptions, audio: src };
      applyAudio(src);
      // 语义与 MountOptions.audio:null 不同：这里的 null 按文档是
      // 「回落内置模拟源」，不是静音（禁用只在挂载选项里表达）
      rt.audioDisabled = false;
    },

    // 系统媒体源。与 setAudio 同纪律：只存引用、换场景不清空，
    // scene 与 web 两条装配路径读同一个 rt.mediaSource。
    // 注意语义与 MountOptions.media:null 不同：这里的 null 按文档是
    // 「回落内置模拟源」，不是禁用（禁用只在挂载选项里表达）。
    setMedia(src: MediaSource | null) {
      currentOptions = { ...currentOptions, media: src };
      rt.mediaSource = src ?? null;
      rt.mediaDisabled = false;
    },

    // 媒体控制面。装配后由 mountScene 写入 rt.mediaCtl；未装配（或媒体/网页
    // 壁纸尚无控制面）时给一个惰性替身，读快照得空、控制方法静默无效 ——
    // 让调用方能无条件 `wp.media.playPause()` 而不必先判空。
    get media(): MediaControl {
      const ctl = rt.mediaCtl as unknown as MediaControl | undefined;
      if (ctl) return ctl;
      const empty = {
        hasMedia: false, state: 0, title: "", artist: "", album: "", albumArtist: "",
        position: 0, duration: 0, hasThumbnail: false,
        primaryColor: mediaColor(0, 0, 0), secondaryColor: mediaColor(0, 0, 0),
        tertiaryColor: mediaColor(0, 0, 0), textColor: mediaColor(1, 1, 1),
        highContrastColor: mediaColor(1, 1, 1),
        trackIndex: 0, lyrics: [] as Array<[number, string]>, lyricLine: "", lyricIndex: -1,
      } as MediaControl["snapshot"];
      const noop = () => empty;
      return {
        get snapshot() {
          return empty;
        },
        skipNext: noop, skipPrevious: noop, play: noop, pause: noop, playPause: noop,
      };
    },

    // 外部指针注入。pointerCtl 由 mountScene / mountWeb 各自装配时设置，
    // 媒体壁纸不设 —— 那时这里静默无效，与整页渲染器的 __wp.pushPointer 一致。
    pushPointer(u: number, v: number, buttons?: number, mods?: number) {
      rt.pointerCtl?.push({ u, v, buttons, mods });
    },
    pointerLeave() {
      rt.pointerCtl?.leave();
    },
    // 滚轮注入。wheel 是可选方法，只有 mountWeb 实现 —— 场景壁纸没有滚轮语义
    // （WE 沙箱无滚轮 API，194 张场景壁纸零消费），此处与媒体壁纸一样静默无效。
    pushWheel(dx: number, dy: number, mode?: number, mods?: number) {
      rt.pointerCtl?.wheel?.({ dx, dy, mode, mods });
    },

    async load(source: Source) {
      // 换源前释放旧源（mediaSource(File) 的 objectURL）。同一个源重复 load
      // 不释放：那会把还在用的 blob URL revoke 掉，视频立刻变黑。
      const prev = currentOptions.source;
      if (prev && prev !== source) {
        try {
          prev.dispose?.();
        } catch {
          /* 忽略 */
        }
      }
      if (destroyed) {
        // 终态：destroy 之后不再复活（原先会重新装配出整场景 + rAF）。
        // 用**拒绝**而不是静默 no-op 收场：destroy 已经把 onDiagnostic 清掉、
        // mediaBase 缺省时连 /diag 的 Image 通道也是关的 —— 「no-op + 上报」在库形态下
        // 仍然是静默的，而静默正是这轮要消灭的东西（issue #9 / §3.5 同理）。
        // 调用方在清理路径里忘了 catch 会看到一条 unhandled rejection —— 那正是它该知道的。
        throw new Error("实例已销毁：实例是终态，load 不会复活它（请重新 mount()）");
      }
      const g = beginGen();
      currentOptions = { ...currentOptions, source };
      wireOptions(currentOptions);
      const cfg = await resolveMountConfig(boundEl, currentOptions);
      // destroy 落在上面这个 await 的窗口里时，settlePending 还没装上（那是 armFirstFrame
      // 的事），所以这里必须自己收尾：明确拒绝 + 把刚建的画布撤掉，不留孤儿元素。
      if (destroyed) {
        releaseOwnCanvas(cfg, boundEl);
        throw new Error("实例已销毁：加载未完成");
      }
      if (!isCurrent(g)) return; // 被新的一次 load 取代：静默退出（调用方 await 的是新那次）
      // scene 与媒体都画在 canvas 上（resolveMountConfig 里 ensureSceneCanvas 取到
      // 的那一块）；网页路径没有 canvas，boundEl 保持调用方传入的容器。
      if (cfg.type !== "web" && cfg.canvas instanceof HTMLCanvasElement) {
        boundEl = cfg.canvas;
      }
      rt.cfg = cfg;
      rt.paused = false;
      rt.info = undefined;
      resetCoverAlign(rt);
      if (currentOptions.properties) {
        rt.liveUserProps = { ...currentOptions.properties };
      }
      const firstFrame = armFirstFrame(g);
      const failure = armFailure(g);
      const watchdog = armWatchdog(g);
      mountWallpaper(rt, cfg);
      try {
        await Promise.race([firstFrame, failure.promise, watchdog.promise]);
      } finally {
        settlePending = null;
        failure.off();
        watchdog.off();
      }
    },

    release() {
      if (destroyed) {
        reportDiag(rt, rt.cfg, "release: 实例已销毁，忽略本次调用", "warn");
        return;
      }
      clear(rt);
    },
    restore() {
      if (destroyed) {
        reportDiag(rt, rt.cfg, "restore: 实例已销毁，忽略本次调用", "warn");
        return;
      }
      remountCurrent();
    },
    /**
     * 销毁实例并释放全部运行时资源（GL 上下文/视频/音频/监听/来源 blob）。
     *
     * `releasePkgCache: true` 时连带淘汰本实例 source.key 的 scene.pkg 解析缓存。
     * 缓存默认跨实例保留（同壁纸重挂不重新下载），宿主切换壁纸后销毁旧实例时
     * 旧包还会压在缓存里（上限 2 份/512MB），桌面壁纸宿主逐张换、不存在"回头
     * 再挂旧壁纸"的模式，销毁即放弃才有可预期的内存曲线。
     * 多实例共享同一 key 时，另一实例只是下次重挂多一次下载，不影响正确性。
     */
    destroy(opts?: { releasePkgCache?: boolean }) {
      // 先置终态、再作废代际，最后才拆运行时：顺序反了的话，正在飞的装配体会在
      // destroyRuntime 与 gen++ 之间的窗口里继续往下走（复活）。
      destroyed = true;
      gen++;
      const pending = settlePending;
      settlePending = null;
      pending?.(); // 挂起中的 mount()/load() 明确 reject，不留悬空 Promise
      destroyRuntime(rt);
      if (opts?.releasePkgCache) {
        dropPkgCache(rt.cfg.source?.key ?? currentOptions.source?.key);
      }
      // 释放来源占用的资源：mediaSource(File) 的 objectURL 不 revoke
      // 就是每换一次壁纸泄漏一个几十 MB 的 blob
      try {
        currentOptions.source?.dispose?.();
      } catch {
        /* 释放失败不阻断销毁 */
      }
      rt.onDiagnostic = undefined;
      rt.onError = undefined;
      rt.onFirstFrame = undefined;
      rt.onSceneInfo = undefined;
      events.ready.length = 0;
      events.error.length = 0;
      events.diagnostic.length = 0;
    },

    get stats() {
      return frameStats(rt);
    },
    get info() {
      return (rt.info as SceneInfo) ?? null;
    },

    on<K extends keyof SceneEvents>(ev: K, fn: SceneEvents[K]) {
      const list = events[ev] as Array<SceneEvents[K]>;
      list.push(fn);
      return () => {
        const i = list.indexOf(fn);
        if (i >= 0) list.splice(i, 1);
      };
    },
  };

  const applyOptions = async (o: MountOptions) => {
    // 同 load()：终态实例上的挂载请求明确拒绝，不静默 no-op
    if (destroyed) throw new Error("实例已销毁：实例是终态，不能用它继续挂载");
    const g = beginGen();
    currentOptions = o;
    wireOptions(o);
    const cfg = await resolveMountConfig(el, o);
    if (destroyed) {
      releaseOwnCanvas(cfg, el);
      throw new Error("实例已销毁：挂载未完成");
    }
    if (!isCurrent(g)) return;
    // 同 load()：scene 与媒体都以 canvas 为绑定元素，网页保持容器
    if (cfg.type !== "web" && cfg.canvas instanceof HTMLCanvasElement) {
      boundEl = cfg.canvas;
    }
    rt.cfg = cfg;
    // autoplay:false 不能在装配前就置 paused —— scene/media 的 kickLoop 会直接
    // 掉头返回，渲染循环一帧都不跑，唯一触发 onFirstFrame 的地方永远到不了，
    // 于是 mount() 的 Promise 既不 resolve 也不 reject，**永久挂起**
    // （web 路径不受影响：它在 iframe load 时无条件触发首帧）。
    // 正解是照常装配、出完首帧再暂停：调用方拿到的是"已就绪但静止在第一帧"，
    // 这也正是 autoplay:false 的语义。
    rt.paused = false;
    rt.info = undefined;
    resetCoverAlign(rt);
    if (o.properties && Object.keys(o.properties).length) {
      rt.liveUserProps = { ...o.properties };
    }
    const firstFrame = armFirstFrame(g);
    const failure = armFailure(g);
    const watchdog = armWatchdog(g);
    mountWallpaper(rt, rt.cfg);
    try {
      await Promise.race([firstFrame, failure.promise, watchdog.promise]);
    } finally {
      settlePending = null;
      failure.off();
      watchdog.off();
    }
    if (!isCurrent(g)) return; // 等首帧期间被 destroy：不要再 pause/setVolume/setProperties
    if (o.autoplay === false) instance.pause();
    if ((o.volume ?? 0) > 0) instance.setVolume(o.volume as number);
    // 网页种子属性已在 HTML 改写时灌入；再推一次覆盖热更路径
    if (o.properties && Object.keys(o.properties).length) instance.setProperties(o.properties);
  };

  (instance as unknown as { __applyOptions?: (o: MountOptions) => Promise<void> }).__applyOptions =
    applyOptions;

  return instance;
}

/**
 * 把一张 WE 壁纸（scene 或 web）挂到元素上。Promise 在首帧/iframe load 后 resolve。
 * 网页壁纸推荐空 `<div>`；传入 canvas 时 iframe 挂到其父节点。
 */
export async function mount(
  el: HTMLElement,
  options: MountOptions,
): Promise<SceneInstance> {
  const instance = createScene(el, options);
  const withApply = instance as unknown as { __applyOptions: (o: MountOptions) => Promise<void> };
  try {
    await withApply.__applyOptions(options);
  } catch (e) {
    // 失败/超时时调用方拿不到实例就没法回收（GL 上下文、画布、监听、pkg 缓存全留着）。
    // 看门狗刻意**不**替调用方销毁（它可能想再等等极慢的冷启动），所以这里把实例
    // 附在错误上：`catch (e) { e.instance?.destroy() }` 就能收尾，也可以选择继续等。
    const err = e instanceof Error ? e : new Error(String(e));
    if (!("instance" in err)) {
      Object.defineProperty(err, "instance", { value: instance, enumerable: false, configurable: true });
      err.message += "（实例已附在 err.instance：可 destroy() 回收，或继续等待）";
    }
    throw err;
  }
  return instance;
}
